def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    border = grid[0][0]

    row_seps = [
        r for r in range(h)
        if all(value == border for value in grid[r])
    ]
    col_seps = [
        c for c in range(w)
        if all(grid[r][c] == border for r in range(h))
    ]

    out_width = col_seps[1] - col_seps[0] + 1
    result = [[border] * out_width]

    for band in range(len(row_seps) - 1):
        y0, y1 = row_seps[band], row_seps[band + 1]

        patterns = []
        for col in range(len(col_seps) - 1):
            x0, x1 = col_seps[col], col_seps[col + 1]
            pattern = tuple(
                tuple(grid[y][x0 + 1:x1])
                for y in range(y0 + 1, y1)
            )
            patterns.append(pattern)

        counts = Counter(patterns)
        odd = [i for i, pattern in enumerate(patterns) if counts[pattern] == 1]
        selected = odd[0] if odd else min(
            range(len(patterns)), key=lambda i: counts[patterns[i]]
        )

        x0, x1 = col_seps[selected], col_seps[selected + 1]
        for y in range(y0 + 1, y1):
            result.append(grid[y][x0:x1 + 1])
        result.append([border] * out_width)

    return result
